182	}
183	
184	/**
185	 * 计算 SOS 按钮的最佳尺寸
186	 * @param {number} contentWidth - 内容区宽度
187	 * @returns {number} 按钮直径
188	 */
189	export function getSosSize(contentWidth) {
190	  return Math.max(72, Math.round(contentWidth * 0.26))
191	}
