/**
 * 创建脉搏动画控制器 — 基于 sin() 正弦波，视觉平滑自然
 * @param {number} bpm - 心率值
 * @returns {object} { start, stop, getScale, getOpacity, getColor }
 */
export function createPulseAnimator(bpm) {
  var timer = null
  var startTime = 0
  var currentBpm = bpm || 72

  function start() {
    stop()
    startTime = Date.now()
    timer = setInterval(function() { /* 保持活跃 */ }, 50)
  }

  function stop() {
    if (timer) { clearInterval(timer); timer = null }
  }

  function _elapsed() {
    return startTime > 0 ? (Date.now() - startTime) / 1000 : 0
  }

  function getScale() {
    // 正弦脉搏：systolic(收缩) sharp peak, diastolic(舒张) gentle valley
    var cycle = currentBpm > 0 ? _elapsed() * (currentBpm / 60) : 0
    var phase = (cycle % 1) * Math.PI * 2
    // 非对称波形：快速收缩 + 慢速舒张
    var v = Math.sin(phase)
    // 压缩负半周，放大正半周 → 收缩感更强
    var asymmetric = v > 0 ? Math.pow(v, 0.6) : -Math.pow(-v, 1.8) * 0.4
    return 1.0 + asymmetric * 0.07
  }

  function getOpacity() {
    var cycle = currentBpm > 0 ? _elapsed() * (currentBpm / 60) : 0
    var phase = (cycle % 1) * Math.PI * 2
    var v = Math.sin(phase)
    return 0.92 + (v > 0 ? v * 0.08 : v * 0.03)
  }

  /**
   * 心率颜色过渡：正常绿 → 偏高橙 → 危险红
   * @returns {string} CSS 颜色值
   */
  function getColor(hr) {
    hr = hr || currentBpm
    if (hr <= 100) return "#3ee6b0"       // 正常：绿色
    if (hr >= 140) return "#ff5d50"       // 危险：红色
    // 100-140 渐变：绿 → 橙 → 红
    var t = (hr - 100) / 40
    var r = Math.round(62 + (255 - 62) * t)
    var g = Math.round(230 + (93 - 230) * t)
    var b = Math.round(176 + (80 - 176) * t)
    return "rgb(" + r + "," + g + "," + b + ")"
  }

  function updateBpm(newBpm) {
    currentBpm = newBpm || 72
  }

  return { start: start, stop: stop, getScale: getScale, getOpacity: getOpacity, getColor: getColor, updateBpm: updateBpm }
}

