/**
 * 创建通用按压反馈控制器
 * @param {number} [count] - 需要跟踪的按压项数量（可选）
 * @returns {object} { bind, isPressed, getStyle, press, release }
 */
export function createPressFeedback(count) {
  var pressed = {}
  return {
    bind: function(id) { return { onTouchStart: function() { pressed[id] = true }, onTouchEnd: function() { pressed[id] = false } } },
    isPressed: function(id) { return !!pressed[id] },
    press: function(id) { pressed[id] = true },
    release: function(id) { pressed[id] = false },
    getStyle: function(id, normalStyle) {
      if (pressed[id]) {
        return (normalStyle || "") + " transform: scale(0.96); opacity: 0.82;"
      }
      return normalStyle || ""
    }
  }
}

