/**
 * 创建页面入场过渡动画
 * 用法：在 onInit 中创建，在 onShow 中 trigger
 * @param {object} [opts] - 配置项
 * @param {number} [opts.duration=250] - 动画时长 ms
 * @param {number} [opts.translateY=15] - Y轴偏移量 px
 * @param {number} [opts.delay=0] - 延迟触发 ms
 * @returns {object} { trigger, getStyle, reset }
 */
export function createPageTransition(opts) {
  opts = opts || {}
  var duration = opts.duration || 250
  var maxTranslateY = opts.translateY || 15
  var delay = opts.delay || 0

  var opacity = 0
  var translateY = maxTranslateY
  var done = false
  var timer = null

  function trigger() {
    if (done) return
    if (timer) { clearTimeout(timer); timer = null }
    if (delay > 0) {
      timer = setTimeout(function() { _animate() }, delay)
    } else {
      _animate()
    }
  }

  function _animate() {
    var startTime = Date.now()
    function frame() {
      var elapsed = Date.now() - startTime
      var t = Math.min(elapsed / duration, 1)
      var eased = easeOutCubic(t)
      opacity = eased
      translateY = maxTranslateY * (1 - eased)
      if (t < 1) {
        setTimeout(frame, 16)
      } else {
        done = true
      }
    }
    frame()
  }

  function getStyle() {
    return "opacity: " + opacity.toFixed(3) + "; transform: translateY(" + translateY.toFixed(1) + "px);"
  }

  function reset() {
    opacity = 0
    translateY = maxTranslateY
    done = false
    if (timer) { clearTimeout(timer); timer = null }
  }

  return { trigger: trigger, getStyle: getStyle, reset: reset }
}

